/**
 * ============================================================================
 * FULL-STACK E-COMMERCE TECH STORE SEEDER SCRIPT
 * Populates MongoDB Atlas with 100+ realistic electronics & tech gear
 * Also creates a default admin user for testing.
 *
 * Run with: node seeder.js
 * Or: npm run data:import
 * Destroy with: node seeder.js --destroy
 * ============================================================================
 */

import mongoose from 'mongoose';
import dotenv from 'dotenv';
import bcrypt from 'bcryptjs';

dotenv.config();

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/techvault';

// ─── INLINE SCHEMAS (Self-contained for standalone execution) ────────────────

const UserSchema = new mongoose.Schema(
  {
    name: { type: String, required: true, trim: true },
    email: { type: String, required: true, unique: true, lowercase: true, trim: true },
    password: { type: String, required: true, select: false },
    role: { type: String, enum: ['user', 'admin'], default: 'user' },
    addresses: [{ fullName: String, phone: String, street: String, city: String, state: String, zipCode: String, country: String, isDefault: { type: Boolean, default: false } }],
    wishlist: [{ type: mongoose.Schema.Types.ObjectId, ref: 'Product' }],
    refreshToken: { type: String, select: false },
    isActive: { type: Boolean, default: true },
    avatar: { type: String, default: '' },
  },
  { timestamps: true }
);

const ProductSchema = new mongoose.Schema(
  {
    title: { type: String, required: true, trim: true },
    slug: { type: String, required: true, unique: true, lowercase: true },
    brand: { type: String, required: true },
    category: {
      type: String,
      required: true,
      enum: ['mobiles', 'laptops', 'tablets', 'audio', 'pc-components', 'gaming-gear'],
    },
    price: { type: Number, required: true },
    discountPrice: { type: Number, default: 0 },
    stock: { type: Number, required: true, default: 10 },
    images: [{ type: String, required: true }],
    description: { type: String, required: true },
    specs: { type: Map, of: String },
    rating: { type: Number, default: 4.8 },
    numReviews: { type: Number, default: 24 },
    isFeatured: { type: Boolean, default: false },
  },
  { timestamps: true }
);

const User = mongoose.models.User || mongoose.model('User', UserSchema);
const Product = mongoose.models.Product || mongoose.model('Product', ProductSchema);

