// ─── HELPERS ─────────────────────────────────────────────────────────────────
function generateSlug(text) {
  return text.toString().toLowerCase().trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// ─── SEED DATABASE ───────────────────────────────────────────────────────────
async function seedDatabase() {
  try {
    console.log('\n==================================================');
    console.log('🔄 Connecting to MongoDB Atlas...');
    console.log('==================================================\n');

    await mongoose.connect(MONGO_URI);
    console.log('✅ Connected to MongoDB successfully.');

    // Check for --destroy flag
    if (process.argv.includes('--destroy')) {
      console.log('🗑️  Destroying all data...');
      await Product.deleteMany({});
      await User.deleteMany({});
      console.log('💥 All data destroyed.');
      await mongoose.connection.close();
      process.exit(0);
    }

    // Clear existing data
    console.log('🗑️  Clearing existing data...');
    await Product.deleteMany({});
    await User.deleteMany({});
    console.log('🧹 Collections cleared.');

    // ── Create Admin User ────────────────────────────────────────
    console.log('👤 Creating admin user...');
    const salt = await bcrypt.genSalt(12);
    const hashedPassword = await bcrypt.hash('Admin@123', salt);

    await User.create({
      name: 'Admin',
      email: 'admin@techvault.com',
      password: hashedPassword,
      role: 'admin',
      isActive: true,
    });
    console.log('✅ Admin user created:');
    console.log('   📧 Email: admin@techvault.com');
    console.log('   🔑 Password: Admin@123');
    console.log('   👑 Role: admin');

    // ── Create Test User ─────────────────────────────────────────
    const userHashedPassword = await bcrypt.hash('User@123', salt);
    await User.create({
      name: 'Test User',
      email: 'user@techvault.com',
      password: userHashedPassword,
      role: 'user',
      isActive: true,
    });
    console.log('✅ Test user created:');
    console.log('   📧 Email: user@techvault.com');
    console.log('   🔑 Password: User@123');

    // ── Seed Products ────────────────────────────────────────────
    console.log(`\n📦 Formatting ${rawCatalog.length} realistic tech items...`);
    const formattedProducts = rawCatalog.map((item, index) => ({
      ...item,
      slug: `${generateSlug(item.title)}-${index + 101}`,
    }));

    console.log(`🚀 Inserting ${formattedProducts.length} products with 4K assets...`);
    const inserted = await Product.insertMany(formattedProducts);

    console.log('\n==================================================');
    console.log(`🎉 SUCCESS! Seeded ${inserted.length} products + 2 users!`);
    console.log('==================================================');
    console.log('📊 Category Breakdown:');
    const counts = {};
    inserted.forEach((p) => { counts[p.category] = (counts[p.category] || 0) + 1; });
    console.table(counts);

    await mongoose.connection.close();
    console.log('🔌 Connection closed. Seeder finished.');
    process.exit(0);
  } catch (error) {
    console.error('\n❌ Seeding Error:', error);
    if (mongoose.connection.readyState !== 0) await mongoose.connection.close();
    process.exit(1);
  }
}

seedDatabase();
